from pathlib import Path
import json,shlex,subprocess
S=Path(__file__).resolve().parent;B=S.parents[2]
sql="""SELECT jsonb_build_object('events',(SELECT jsonb_agg(jsonb_build_object('id_evento',e.id_evento,'tag',e.tag,'name',e.nome_evento,'start',e.data_inicial,'end',e.data_final,'ativo',e.ativo,'city',e.cidade,'state',e.estado,'provider',e.id_fornecedor,'source',e.url_hotsite,'registration',e.url_inscricao,'status',e.status_evento,'redirect_tag',e.tag_301,'hash',md5(to_jsonb(e)::text)) ORDER BY e.id_evento) FROM public.tb_evento_corridas e WHERE tag IN ('2026-corrida-das-cores-da-amazonia','2027-corrida-das-cores-da-amazonia')),'references',(SELECT jsonb_agg(jsonb_build_object('table',c.conrelid::regclass::text,'constraint',c.conname,'column',a.attname)) FROM pg_constraint c JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=ANY(c.conkey) WHERE c.contype='f' AND c.confrelid='public.tb_evento_corridas'::regclass))::text payload"""
helpers=(B/'_codex/scripts/deploy_estudo.py').read_text().split('def remote(')[0].replace('ROOT=Path(__file__).resolve().parents[2]',"ROOT=Path('/var/www/business.roadrunners.run')").replace('runner_dba','runnerhub')
remote=helpers+'''\np=json.load(sys.stdin);body='transaction {'+raw_query("SET TRANSACTION READ ONLY; SET LOCAL statement_timeout='20s'",'qLimits')+raw_query(p['sql'])+'}report=deserializeJSON(q.payload[1]);';print(json.dumps(bridge(ROOT,body)))'''
ssh=['ssh','-o','BatchMode=yes','-o','ConnectTimeout=10','-o','StrictHostKeyChecking=yes','-i','/Users/leonardosobral/.ssh/webs','root@ssh.runnerhub.run']
cp=subprocess.run(ssh+['python3 -c '+shlex.quote(remote)],input=json.dumps({'sql':sql}),capture_output=True,text=True,timeout=100);assert cp.returncode==0,cp.stderr[-2000:]
r=json.loads(cp.stdout);(S/'amazonia-readonly.json').write_text(json.dumps(r,ensure_ascii=False,indent=2));print(json.dumps(r,ensure_ascii=False,indent=2))
